def parse_json(s: str) -> object:
    """
    A simple recursive descent parser for JSON strings that converts
    them into Python objects. It supports strings, numbers, booleans,
    null, arrays, and objects, parsing them character by character.
    """

    class JSONParseError(Exception):
        pass

    idx = 0

    def parse_value():
        nonlocal idx
        char = s[idx]

        if char == '"':
            return parse_string()
        elif char.isdigit() or char == '-':
            return parse_number()
        elif s.startswith('true', idx):
            idx += 4
            return True
        elif s.startswith('false', idx):
            idx += 5
            return False
        elif s.startswith('null', idx):
            idx += 4
            return None
        elif char == '[':
            return parse_array()
        elif char == '{':
            return parse_object()
        else:
            raise JSONParseError(f"Unexpected character: {char}")

    def parse_string():
        nonlocal idx
        result = []
        idx += 1  # skip opening quote
        while idx < len(s):
            char = s[idx]
            if char == '"':
                idx += 1  # skip closing quote
                break
            elif char == '\\':
                idx += 1
                char = s[idx]  # next character is escaped
                if char in '"\\/bfnrt':
                    result.append({
                        '"': '"',
                        '\\': '\\',
                        '/': '/',
                        'b': '\b',
                        'f': '\f',
                        'n': '\n',
                        'r': '\r',
                        't': '\t'
                    }[char])
                else:
                    raise JSONParseError(f"Invalid escape character: {char}")
            else:
                result.append(char)
            idx += 1
        return ''.join(result)

    def parse_number():
        nonlocal idx
        start_idx = idx
        if s[idx] == '-':
            idx += 1
        while idx < len(s) and s[idx].isdigit():
            idx += 1
        if idx < len(s) and s[idx] == '.':
            idx += 1
            while idx < len(s) and s[idx].isdigit():
                idx += 1
        num_str = s[start_idx:idx]
        if '.' in num_str:
            return float(num_str)
        return int(num_str)

    def parse_array():
        nonlocal idx
        idx += 1  # skip opening bracket
        arr = []
        while idx < len(s):
            if s[idx] == ']':
                idx += 1  # skip closing bracket
                return arr
            arr.append(parse_value())
            if s[idx] == ',':
                idx += 1  # skip comma
            elif s[idx] == ']':
                idx += 1  # skip closing bracket
                return arr
            else:
                raise JSONParseError(f"Expected ',' or ']', got: {s[idx]}")

    def parse_object():
        nonlocal idx
        idx += 1  # skip opening brace
        obj = {}
        while idx < len(s):
            if s[idx] == '}':
                idx += 1  # skip closing brace
                return obj
            key = parse_string()
            if s[idx] != ':':
                raise JSONParseError(f"Expected ':', got: {s[idx]}")
            idx += 1  # skip colon
            value = parse_value()
            obj[key] = value
            if s[idx] == ',':
                idx += 1  # skip comma
            elif s[idx] == '}':
                idx += 1  # skip closing brace
                return obj
            else:
                raise JSONParseError(f"Expected ',' or '}', got: {s[idx]}")

    value = parse_value()
    if idx != len(s):
        raise JSONParseError(f"Unexpected trailing data at index {idx}: {s[idx:]}")
    return value

def parse_json(s: str) -> object:
    """
    A state-machine based parser for JSON strings that uses an iterative approach
    to convert JSON structured strings to Python native objects. This technique
    handles different states to track parsing contexts for strings, numbers,
    booleans, nulls, arrays, and objects without recursion.
    """

    class JSONParseError(Exception):
        pass

    idx = 0
    length = len(s)
    state = 0  # 0: start, 1: parsing string, 2: parsing number, 3: parsing array, 4: parsing object
    stack = []  # Will be used to track the context 

    def next_char():
        nonlocal idx
        if idx < length:
            char = s[idx]
            idx += 1
            return char
        return None

    def parse_string():
        result = []
        char = next_char()
        while char != '"':
            if char == '\\':
                char = next_char()
                escape_chars = {
                    '"': '"', '\\': '\\', '/': '/', 'b': '\b', 
                    'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'
                }
                if char in escape_chars:
                    result.append(escape_chars[char])
                else:
                    raise JSONParseError("Invalid escape character: {}".format(char))
            else:
                result.append(char)
            char = next_char()
        return ''.join(result)

    def parse_number():
        num_str = []
        char = next_char()
        if char == '-':
            num_str.append(char)
            char = next_char()
        while char is not None and (char.isdigit() or char == '.'):
            num_str.append(char)
            char = next_char()
        idx -= 1  # Undo the last increment
        return int(''.join(num_str)) if '.' not in num_str else float(''.join(num_str))

    while idx < length:
        char = next_char()
        if char in ' \n\t\r':
            continue
        if char == '"':
            stack.append(parse_string())
        elif char.isdigit() or char == '-':
            idx -= 1  # undo the increment
            stack.append(parse_number())
        elif char == 't':
            if s.startswith('true', idx - 1):
                stack.append(True)
                idx += 3  # skip "rue"
            else:
                raise JSONParseError("Invalid token following 't'")
        elif char == 'f':
            if s.startswith('false', idx - 1):
                stack.append(False)
                idx += 4  # skip "alse"
            else:
                raise JSONParseError("Invalid token following 'f'")
        elif char == 'n':
            if s.startswith('null', idx - 1):
                stack.append(None)
                idx += 3  # skip "ull"
            else:
                raise JSONParseError("Invalid token following 'n'")
        elif char == '[':
            state = 3  # indicates array state
            arr = []
            while True:
                if stack and stack[-1] == ']':
                    stack.pop()  # closing bracket
                    break
                if char == ']':
                    arr.append(None)  # empty array
                    break
                idx -= 1  # undo increment for a correct next_char call
                arr.append(stack.pop())
                char = next_char()
                if char == ',':
                    continue
                elif char == ']':
                    stack.append(arr)
                    break
                else:
                    raise JSONParseError("Expected ',' or ']', got: {}".format(char))
        elif char == '{':
            state = 4  # indicates object state
            obj = {}
            key = None
            while True:
                if stack and stack[-1] == '}':
                    stack.pop()  # closing brace
                    break
                if char == '}':
                    obj[key] = None  # empty object
                    break
                idx -= 1
                key = stack.pop()
                if next_char() != ':':
                    raise JSONParseError("Expected ':', got: {}".format(char))
                value = stack.pop()
                obj[key] = value
                char = next_char()
                if char == ',':
                    continue
                elif char == '}':
                    stack.append(obj)
                    break
                else:
                    raise JSONParseError("Expected ',' or '}', got: {}".format(char))
        else:
            raise JSONParseError("Unexpected character: {}".format(char))

    if len(stack) != 1:
        raise JSONParseError("Parsing Error: Unexpected stack size: {}".format(len(stack)))
    return stack[0]

