def parse_json(s: str) -> object:
    """
    A recursive descent parsing approach is used to parse the JSON string.
    Each type of JSON construct (string, number, object, array, etc.) has a dedicated parsing function,
    leading to clear structure and ease of comprehension.
    """

    class JSONParseError(Exception):
        pass

    index = 0
    length = len(s)

    def parse_value():
        """Parse a JSON value."""
        skip_whitespace()
        if index >= length:
            raise JSONParseError("Unexpected end of JSON input.")

        char = s[index]
        if char == '"':
            return parse_string()
        elif char.isdigit() or char == '-':
            return parse_number()
        elif s.startswith('true', index):
            index += 4
            return True
        elif s.startswith('false', index):
            index += 5
            return False
        elif s.startswith('null', index):
            index += 4
            return None
        elif char == '[':
            return parse_array()
        elif char == '{':
            return parse_object()
        else:
            raise JSONParseError(f"Unexpected character: {char}")

    def parse_string():
        """Parse a JSON string with escape sequences."""
        nonlocal index
        result = []
        index += 1  # Skip opening quote

        while index < length:
            char = s[index]
            if char == '"':
                index += 1  # Skip closing quote
                return ''.join(result)
            elif char == '\\':
                index += 1  # Skip escape character
                if index >= length:
                    raise JSONParseError("Unexpected end of JSON input after escape.")
                escape_char = s[index]
                escapes = {
                    '"': '"', '\\': '\\', '/': '/',
                    'b': '\b', 'f': '\f', 'n': '\n',
                    'r': '\r', 't': '\t'
                }
                if escape_char in escapes:
                    result.append(escapes[escape_char])
                else:
                    raise JSONParseError(f"Invalid escape sequence: \\{escape_char}")
            else:
                result.append(char)
            index += 1

        raise JSONParseError("Unterminated string.")

    def parse_number():
        """Parse a JSON number (integer or float)."""
        nonlocal index
        start = index

        if s[index] == '-':
            index += 1

        while index < length and s[index].isdigit():
            index += 1

        if index < length and s[index] == '.':
            index += 1
            while index < length and s[index].isdigit():
                index += 1

        num_str = s[start:index]
        if '.' in num_str:
            return float(num_str)
        return int(num_str)

    def parse_array():
        """Parse a JSON array."""
        nonlocal index
        result = []
        index += 1  # Skip opening '['

        while index < length:
            skip_whitespace()
            if s[index] == ']':
                index += 1  # Skip closing ']'
                return result

            result.append(parse_value())
            skip_whitespace()

            if index < length and s[index] == ',':
                index += 1  # Skip comma
            elif index < length and s[index] != ']':
                raise JSONParseError(f"Unexpected character in array: {s[index]}")

        raise JSONParseError("Unterminated array.")

    def parse_object():
        """Parse a JSON object."""
        nonlocal index
        result = {}
        index += 1  # Skip opening '{'

        while index < length:
            skip_whitespace()
            if s[index] == '}':
                index += 1  # Skip closing '}'
                return result

            key = parse_string()
            skip_whitespace()
            if s[index] != ':':
                raise JSONParseError("Expected ':' after key in object.")
