            value = parse_value()
            result[key] = value
            skip_whitespace()

            if index < length and s[index] == ',':
                index += 1  # Skip comma
            elif index < length and s[index] != '}':
                raise JSONParseError(f"Unexpected character in object: {s[index]}")

        raise JSONParseError("Unterminated object.")

    def skip_whitespace():
        """Skip whitespace characters in the JSON string."""
        nonlocal index
        while index < length and s[index].isspace():
            index += 1

    result = parse_value()
    skip_whitespace()
